69: 
70:     return () => {
71:       window.removeEventListener("accountIdChanged", handleAccountIdChange);
72:       window.removeEventListener("storage", handleStorageChange);
73:     };
74:   }, []);
75: 
76:   const handleRefreshAccount = useCallback(() => {
77:     window.location.reload();
78:   }, []);
79: 
80:   if (loadingAccount) {
81:     return (
82:       <Provider store={store}>
83:         <QueryProvider>
84:           <div className={styles.container}>
85:             <Loading text="Carregando..." size="medium" />
86:           </div>
87:         </QueryProvider>
88:       </Provider>
89:     );
