3: const API_BASE_URL = getApiBaseUrl();
4: const REQUEST_TIMEOUT = 30000;
5: 
6: function getAuthToken(): string | null {
7:   if (typeof window !== "undefined" && window.localStorage) {
8:     return localStorage.getItem("token");
9:   }
10:   return null;
11: }
12: 
13: interface TimeoutAbortController extends AbortController {
14:   timeoutId?: NodeJS.Timeout;
15: }
16: 
17: function createTimeoutController(timeout: number): TimeoutAbortController {
18:   const controller = new AbortController() as TimeoutAbortController;
19:   const timeoutId = setTimeout(() => {
20:     controller.abort();
21:   }, timeout);
22:   controller.timeoutId = timeoutId;
23:   return controller;
24: }
25: 
26: export async function fetchApi(
27:   url: string,
28:   options: RequestInit & { timeout?: number } = {}
29: ): Promise<Response> {
30:   const { timeout = REQUEST_TIMEOUT, ...fetchOptions } = options;
31: 
32:   const token = getAuthToken();
33:   const headers: HeadersInit = {
34:     "Content-Type": "application/json",
35:     ...fetchOptions.headers,
36:   };
37: 
38:   if (token) {
39:     headers["Authorization"] = `Bearer ${token}`;
40:   }
41: 
42:   const timeoutController = createTimeoutController(timeout);
43: 
44:   let signal = timeoutController.signal;
45:   if (fetchOptions.signal) {
46:     const combinedController = new AbortController();
47:     const abort = () => {
48:       if (timeoutController.timeoutId) {
49:         clearTimeout(timeoutController.timeoutId);
50:       }
51:       combinedController.abort();
52:     };
53:     timeoutController.signal.addEventListener("abort", abort);
54:     fetchOptions.signal.addEventListener("abort", abort);
55:     signal = combinedController.signal;
56:   }
57: 
58:   let response: Response;
59:   try {
60:     response = await fetch(`${API_BASE_URL}${url}`, {
61:       ...fetchOptions,
62:       headers,
63:       signal,
64:     });
65:   } catch (error) {
66:     if (error instanceof Error && error.name === "AbortError") {
67:       throw new Error("timeout: A requisição demorou muito para responder");
68:     }
69:     throw error;
70:   }
71: 
72:   if (!response.ok) {
73:     if (response.status === 401) {
74:       if (typeof window !== "undefined" && window.localStorage) {
75:         localStorage.removeItem("token");
76:         window.location.href = "/auth";
77:       }
78:       const errorText = await response.text().catch(() => response.statusText);
79:       throw new Error(`Erro na requisição: ${response.status} ${errorText}`);
80:     }
81:     const errorText = await response.text().catch(() => response.statusText);
82:     throw new Error(`Erro na requisição: ${response.status} ${errorText}`);
83:   }
84: 
85:   return response;
86: }

