2: import { getApiBaseUrl } from "@/config/api.config";
3: import { AUTH_REDIRECT_PATH } from "@/constants";
4: 
5: const API_BASE_URL = getApiBaseUrl();
6: const REQUEST_TIMEOUT = 30000;
7: 
8: function getAuthToken(): string | null {
9:   if (typeof window !== "undefined" && window.localStorage) {
10:     return localStorage.getItem("token");
11:   }
12:   return null;
13: }
14: 
15: interface TimeoutAbortController extends AbortController {
16:   timeoutId?: NodeJS.Timeout;
17: }
18: 
19: function createTimeoutController(timeout: number): TimeoutAbortController {
20:   const controller = new AbortController() as TimeoutAbortController;
21:   const timeoutId = setTimeout(() => {
22:     controller.abort();
23:   }, timeout);
24:   controller.timeoutId = timeoutId;
25:   return controller;
26: }
27: 
28: export async function fetchApi(
29:   url: string,
30:   options: RequestInit & { retry?: boolean; timeout?: number } = {}
31: ): Promise<Response> {
32:   const { retry = true, timeout = REQUEST_TIMEOUT, ...fetchOptions } = options;
33: 
34:   const token = getAuthToken();
35:   const headers: HeadersInit = {
36:     "Content-Type": "application/json",
37:     ...fetchOptions.headers,
38:   };
39: 
40:   if (token) {
41:     headers["Authorization"] = `Bearer ${token}`;
42:   }
43: 
44:   const performFetch = async (): Promise<Response> => {
45:     const timeoutController = createTimeoutController(timeout);
46: 
47:     let signal = timeoutController.signal;
48:     if (fetchOptions.signal) {
49:       const combinedController = new AbortController();
50:       const abort = () => {
51:         if (timeoutController.timeoutId) {
52:           clearTimeout(timeoutController.timeoutId);
53:         }
54:         combinedController.abort();
55:       };
56:       timeoutController.signal.addEventListener("abort", abort);
57:       fetchOptions.signal.addEventListener("abort", abort);
58:       signal = combinedController.signal;
59:     }
60: 
61:     let response: Response;
62:     try {
63:       response = await fetch(`${API_BASE_URL}${url}`, {
64:         ...fetchOptions,
65:         headers,
66:         signal,
67:       });
68:     } catch (error) {
69:       if (error instanceof Error && error.name === "AbortError") {
70:         throw new Error("timeout: A requisição demorou muito para responder");
71:       }
72:       throw error;
73:     }
74: 
75:     if (!response.ok) {
76:       if (response.status === 401) {
77:         if (typeof window !== "undefined" && window.localStorage) {
78:           localStorage.removeItem("token");
79:           window.location.href = AUTH_REDIRECT_PATH;
80:         }
81:         const errorText = await response.text().catch(() => response.statusText);
82:         throw new Error(`Erro na requisição: ${response.status} ${errorText}`);
83:       }
84:       const errorText = await response.text().catch(() => response.statusText);
85:       throw new Error(`Erro na requisição: ${response.status} ${errorText}`);
86:     }
87: 
88:     return response;
89:   };
90: 
91:   if (retry) {
92:     return withRetry(performFetch, {
93:       maxRetries: 3,
94:       baseDelay: 1000,
95:     });
96:   }
97: 
98:   return performFetch();
99: }

