5: 
6: /** Rotas que requerem autenticação */
7: export const PROTECTED_ROUTES = [
8:   "/",
9:   "/dashboard",
10:   "/transactions",
11:   "/statement",
12: ] as const;
13: 
14: /** Rotas públicas (não requerem autenticação) */
15: export const PUBLIC_ROUTES = ["/auth"] as const;
16: 
17: /** Tipo para rotas protegidas */
18: export type ProtectedRoute = (typeof PROTECTED_ROUTES)[number];
19: 
20: /** Tipo para rotas públicas */
21: export type PublicRoute = (typeof PUBLIC_ROUTES)[number];
22: 
23: /** Tipo para todas as rotas */
24: export type AppRoute = ProtectedRoute | PublicRoute;
25: 
26: /** Verifica se uma rota é protegida */
27: export function isProtectedRoute(path: string): boolean {
28:   return PROTECTED_ROUTES.includes(path as ProtectedRoute);
29: }
30: 
31: /** Verifica se uma rota é pública */
32: export function isPublicRoute(path: string): boolean {
33:   return PUBLIC_ROUTES.includes(path as PublicRoute);
34: }
